                for c in range(lo + 2, hi - 1):
                    if out[r1][c] == 0:
                        out[r1][c] = 1
            elif c1 == c2:
                lo, hi = sorted((r1, r2))
                for r in range(lo + 2, hi - 1):
                    if out[r][c1] == 0:
